class DiagnosisProbe:
    def run_full_diagnosis(self, train_loader):
        saved = capture_model_mode_rng_and_state()
        metrics, definitions = {}, {}
        try:
            self.view.model.eval()
            for probe in independent_prerequisite_and_descriptive_probes:
                outcome = run_with_local_exception_capture(probe)
                retain_values_definitions_availability_counts_and_runtime(outcome)
            for probe in behavioral_and_optional_probes:
                gate = evaluate_current_prerequisites(probe, metrics)
                if not gate.passed:
                    record_unavailable(probe, gate.actual_reasons)
                else:
                    retain(run_with_local_exception_capture(probe))
            if diagnostic_budget_allows:
                record_clean_fixture_results()
                for fault in preregistered_semantic_faults:
                    with reversible_in_memory_fault(fault):
                        record_probe_detections_and_exercised_coverage()
            return {'metrics': metrics, 'metric_definitions': definitions}
        finally:
            remove_temporary_hooks()
            restore_model_state_mode_and_rng(saved)

